      <div>Museum Night — Premium Cultural Event</div>
      <div style="margin-top:1rem">
        <a href="#" style="color:var(--muted);margin:0 .5rem">Twitter</a>
        <a href="#" style="color:var(--muted);margin:0 .5rem">Instagram</a>
        <a href="#" style="color:var(--muted);margin:0 .5rem">Facebook</a>
      </div>
      <div style="margin-top:2rem;font-size:.8rem">Demo landing page — no real ticket purchase.</div>
      <div style="margin-top:1rem;font-size:.75rem">© 2026 ARTIFACT. All rights reserved.</div>
    </div>
  </footer>

  <!-- Artist Modal -->
  <div class="modal-overlay" id="artistModal">
    <div class="modal">
      <button class="modal-close" id="modalClose" aria-label="Close modal">&times;</button>
      <img class="modal-image" id="modalImage" src="" alt="Artist image">
