  </div>

  <script>
    // Data
    const timelineData = [
      {time:"19:00", title:"Doors Open", desc:"General admission. Welcome glass of sparkling wine.", location:"Main Entrance, The Old Gallery"},
      {time:"19:30", title:"Curator Welcome", desc:"Opening remarks and introduction to the night's program.", location:"Atrium, The Old Gallery"},
      {time:"20:00", title:"Hidden Collection Tour", desc:"Exclusive tour of rarely-seen works from the permanent collection.", location:"West Wing, The Old Gallery"},
      {time:"21:00", title:"Live Ambient Performance", desc:"Improvised ambient soundscape by featured artists.", location:"Central Hall, The Old Gallery"},
      {time:"22:00", title:"Sculpture Hall Projection", desc:"Mapped projection on sculptural works. Visual poetry of light and form.", location:"Sculpture Hall, The Old Gallery"},
      {time:"23:00", title:"Artist Talk", desc:"Conversation with featured artists about process and inspiration.", location:"East Wing Conference Room, The Old Gallery"},
      {time:"00:00", title:"Midnight Gallery Walk", guided:"nocturnal walkthrough with limited lighting.", location:"Gallery-wide, The Old Gallery"},
      {time:"01:00", title:"Closing Sound Session", desc:"Final immersive sound experience to close the event.", location:"Rooftop Terrace, The Old Gallery"}
    ];

    const artistsData = [
      {name:"Marta Kowalska", role:"Contemporary Artist", teaser:"Exploring memory through fragmented porcelain installations.", img:"https://source.unsplash.com/featured/1200x900?gallery,art"},
      {name:"Julian Vance", role:"Performance Artist", teaser:"Live body-performance responding to architectural space.", img:"https://source.unsplash.com/featured/1200x900?exhibition,lights"},
      {name:"Chen Wei", role:"Installation Artist", teaser:"Silent video sculpture examining the relationship between time and object.", img:"https://source.unsplash.com/featured/1200x900?sculpture,museum"},
      {name:"Sophie Duval", role:"Curator", teaser:"Presentation of forgotten museum archives brought to light.", img:"https://source.unsplash.com/featured/1200x900?museum,crowd"},
      {name:"Luca Moretti", role:"New Media Artist", teaser:"Interactive light installation that responds to visitor movement.", img:"https://source.unsplash.com/featured/1200x900?art,installation"},
