    const tierData = [
      {name:"Night Pass", price:"€29", features:["Entry after 19:00","Main exhibition access","Program access"]},
      {name:"Curator Pass", price:"€59", recommended:true, features:["Everything in Night Pass","Hidden collection tour","Reserved artist talk seating"]},
      {name:"Patron Pass", price:"€129", features:["Everything in Curator Pass","VIP lounge access","Signed event print","Priority entrance"]}
    ];

    const faqData = [
      {q:"Is payment processed on this page?", a:"No — this is a demo landing page. No real payment is processed."},
      {q:"Can I arrive late?", a:"Yes — the event runs from 19:00 to 02:00. Late arrival is welcome, though some guided tours have fixed start times."},
      {q:"Are photos allowed?", a:"Photography is permitted in most areas. Flash is discouraged to protect the artworks. Some restricted areas will be marked."},
      {q:"Is the venue accessible?", a:"The Old Gallery has wheelchair access via the main entrance and elevator to all floors. Detailed accessibility notes are available on site."},
      {q:"Can I change my ticket tier?", a:"Tier changes are possible up to 48 hours before the event, subject to availability. Contact the organizers for modifications."},
      {q:"How do I save the event to my calendar?", a:"Use the "Save to Calendar" button in the hero section. It will generate an .ics file you can import into Google Calendar, Apple Calendar, or any calendar app."}
