      const container = document.getElementById('timeline');
      let html = '';
      timelineData.forEach((item,i) => {
        const isLast = i === timelineData.length - 1;
        html += `
          <div class="timeline-item" style="animation-delay: ${i * 0.1}s">
            <span class="timeline-time">${item.time}</span>
            <div>
              <h3 class="timeline-title">${item.title}</h3>
              <p class="timeline-desc">${item.desc}</p>
              <p class="timeline-location">${item.location}</p>
            </div>
          </div>
        `;
      });
      container.innerHTML = html;
    }

    function renderArtists(){
      const container = document.getElementById('artistsGrid');
      let html = '';
      artistsData.forEach((artist,i) => {
        html += `
          <div class="artist-card" style="animation-delay: ${i * 0.1}s">
            <img class="artist-image" src="${artist.img}" alt="${artist.name}" loading="lazy">
            <div class="artist-info">
              <h3 class="artist-name">${artist.name}</h3>
              <p class="artist-role">${artist.role}</p>
              <p class="artist-teaser">${artist.teaser}</p>
              <button class="artist-btn" data-artist-index="${i}">View details</button>
            </div>
          </div>
        `;
      });
      container.innerHTML = html;
    }

    function renderTickets(){
      const container = document.getElementById('tiers');
      let html = '';
      tierData.forEach((tier,i) => {
        const recClass = tier.recommended ? 'tier-recommended' : '';
        html += `
          <div class="tier-card" style="animation-delay: ${i * 0.1}s">
            <span class="${recClass}">${tier.recommended ? 'Recommended' : ''}</span>
            <div>
              <div class="tier-name">${tier.name}</div>
              <div class="tier-price">${tier.price}</div>
              <ul class="tier-features">
                ${tier.features.map(f => `<li>${f}</li>`).join('')}
              </ul>
            </div>
            <button class="select-btn" data-tier-index="${i}">Select Tier</button>
          </div>
        `;
      });
      container.innerHTML = html;
    }

    function renderFAQ(){
      const container = document.getElementById('faqAccordion');
      let html = '';
      faqData.forEach((item,i) => {
        html += `
          <div class="faq-item" style="animation-delay: ${i * 0.1}s">
            <button class="faq-question" aria-expanded="false">
              ${item.q}
              <span class="plus">+</span>
            </button>
            <div class="faq-answer">
              ${item.a}
            </div>
          </div>
        `;
      });
      container.innerHTML = html;

      // Add FAQ click handlers after rendering
      document.querySelectorAll('.faq-question').forEach(btn => {
        btn.addEventListener('click', () => {
          const isActive = btn.classList.toggle('active');
          const answer = btn.nextElementSibling;
          answer.classList.toggle('open', isActive);
          btn.setAttribute('aria-expanded', isActive);
        });
      });
    }

    // Modal functions
    function openArtistModal(index){
      const artist = artistsData[index];
      document.getElementById('modalName').textContent = artist.name;
      document.getElementById('modalRole').textContent = artist.role;
      document.getElementById('modalImage').src = artist.img;
      document.getElementById('modalImage').alt = artist.name;
      document.getElementById('modalBio').innerHTML = `<strong>Bio:</strong> ${getBio(artist.name)}`;
      document.getElementById('artistModal').classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function getBio(name){
      const bios = {
        "Marta Kowalska": "Polish contemporary artist working with porcelain, video, and installation. Her work explores themes of memory, loss, and reconstruction. Exhibited at Warsaw National Museum and Berlin Biennale.",
        "Julian Vance": "Performance and body artist based in Berlin. Creates site-specific works that investigate the relationship between presence, absence, and architectural space. Known for quiet, meditative performances.",
        "Chen Wei": "Chinese installation artist based in Shanghai. Works with video, sound, and found objects to examine temporal relationships and the politics of memory. Solo exhibitions at Power Station of Art.",
        "Sophie Duval": "Curator and researcher focusing on forgotten archives and the politics of museum collection. PhD in Art History, University of Paris. Author of several publications on hidden museum histories.",
        "Luca Moretti": "New media artist working with interactive light, sound, and spatial computing. Creates responsive environments that adapt to visitor presence and movement. Exhibited at Ars Electronica and MoMA PS1.",
        "Anika Patel": "Spatial sound and composition artist. Works with binaural recording and diffusion systems to create immersive audio environments. Recent projects include site-specific sound walks and gallery installations."
      };
      return bios[name] || '';
    }

    function closeArtistModal(){
      document.getElementById('artistModal').classList.remove('active');
      document.body.style.overflow = ''
    }

    document.getElementById('artistModal').addEventListener('click', function(e) {
      if(e.target === e.currentTarget || e.target.classList.contains('modal-close')){
        closeArtistModal()
      }
    })

    document.addEventListener('keydown', function(e) {
      if(e.key === 'Escape' && document.getElementById('artistModal').classList.contains('active')){
        closeArtistModal()
      }
    })

    // Ticket select open modal
    let selectedTier = null;
    document.querySelectorAll('.select-btn').forEach(btn => {
      btn.addEventListener('click', function() {
        const idx = btn.getAttribute('data-tier-index');
        selectedTier = tierData[idx];
        openCheckoutModal(selectedTier)
      })
    })

    function openCheckoutModal(tier){
      document.getElementById('modalTitle').textContent = `Select ${tier.name}`;
      selectedTier = tier;
      document.getElementById('checkoutModal').classList.add('active');
      document.body.style.overflow = 'hidden';
      document.getElementById('ticketForm').reset();
      document.getElementById('successMessage').classList.remove('show')
    }

    function closeCheckoutModal(){
      document.getElementById('checkoutModal').classList.remove('active');
      document.body.style.overflow = ''
    }

    document.getElementById('checkoutModal').addEventListener('click', function(e) {
      if(e.target === e.currentTarget || e.target.classList.contains('checkout-close')){
        closeCheckoutModal()
      }
    })

    document.addEventListener('keydown', function(e) {
      if(e.key === 'Escape' && document.getElementById('checkoutModal').classList.contains('active')){
        closeCheckoutModal()
      }
    })

    document.getElementById('ticketForm').addEventListener('submit', function(e) {
      e.preventDefault()
      const name = document.getElementById('attendeeName').value
      const email = document.getElementById('attendeeEmail').value
      const num = document.getElementById('numTickets').value
      if(!name || !email || !num){
        showToast('Please fill in all fields')
        return
      }
      if(!isValidEmail(email)){
        showToast('Please enter a valid email address')
        return
      }
      document.getElementById('successMessage').classList.add('show')
      setTimeout(closeCheckoutModal, 2000)
      showToast(`Reservation confirmed for ${num} ${selectedTier.name} ticket(s)!`)
    })

    function isValidEmail(email){
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
    }

    // Toast
    function showToast(message){
      const toast = document.getElementById('toast')
      document.getElementById('toastMessage').textContent = message
      toast.classList.add('show')
      setTimeout(() => toast.classList.remove('show'), 5000)
    }

    // Save to Calendar .ics
    function saveToCalendar(){
      const start = "20261018T190000";
      const end = "20261019T020000";
      const title = "ARTIFACT: Museum Night";
      const location = "The Old Gallery, Warsaw";
      const desc = "A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.";

      const icsContent = `BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//ARTIFACT//Museum Night//EN\nBEGIN:VEVENT\nUID:${Date.now()}@artifactmuseumnight\nDTSTAMP:${start}\nDTSTART:${start}\nDTEND:${end}\nSUMMARY:${title}\nDESCRIPTION:${desc}\nLOCATION:${location}\nEND:VEVENT\nEND:VCALENDAR`;

      const blob = new Blob([icsContent], {type: 'text/calendar'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'artifact-museum-night.ics';
      a.click();
      URL.revokeObjectURL(url);
      showToast('Calendar file downloading...')
    }

    // Active nav on scroll
    function activateNav(){
      const sections = document.querySelectorAll('section[id]');
      const navLinks = document.querySelectorAll('.nav-links a');
      const scrollPos = window.scrollY + 100;

      sections.forEach(section => {
        const top = section.offsetTop;
        const height = section.clientHeight;
        if(scrollPos >= top && scrollPos < top + height){
          navLinks.forEach(link => {
            link.classList.remove('active');
            if(link.getAttribute('href') === `#${section.id}`){
              link.classList.add('active')
            }
          })
        }
      })
    }

    // Scroll reveal on view
    function initScrollReveal(){
      const observerOptions = {
        threshold:0.1,
        rootMargin:"0px 0px -50px 0px"
      };
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if(entry.isIntersecting){
            entry.target.style.opacity = '1';
            entry.target.style.transform = 'translateY(0)'
          }
        })
      }, observerOptions);

      document.querySelectorAll('.feature-card, .timeline-item, .artist-card, .tier-card, .faq-item').forEach(el => {
        el.style.opacity = '0';
        el.style.transform = 'translateY(20px)';
        el.style.transition = 'opacity .6s ease-out, transform .6s ease-out';
        observer.observe(el)
      })
    }

    // Mobile menu
    const mobileToggle = document.getElementById('mobileToggle');
    const navLinks = document.getElementById('navLinks');

    mobileToggle.addEventListener('click', function() {
      navLinks.classList.toggle('active');
      mobileToggle.classList.toggle('active')
    })

    // Smooth scroll for nav links
    document.querySelectorAll('.nav-links a').forEach(function(link) {
      link.addEventListener('click', function(e) {
        e.preventDefault();
        const href = link.getAttribute('href');
        if(href.startsWith('#')) {
          const target = document.querySelector(href);
          if(target) {
            const pos = target.offsetTop - 80;
            window.scrollTo({
              top: pos,
              behavior: 'smooth'
            });
          }
        }
      });
    })

    // Initialize
    document.addEventListener('DOMContentLoaded', function() {
      renderTimeline();
      renderArtists();
      renderTickets();
      renderFAQ();

      // Hero metadata
      const metaContainer = document.getElementById('heroMeta');
      const metaHTML = `
        <div class="meta-badge"><span>📅</span>18 October 2026</div>
        <div class="meta-badge"><span>🕐</span>19:00–02:00</div>
        <div class="meta-badge"><span>📍</span>The Old Gallery, Warsaw</div>
      `;
      metaContainer.innerHTML = metaHTML;

      // Hero CTA
      document.getElementById('heroCTA').addEventListener('click', function() {
        document.getElementById('tickets').scrollIntoView({behavior: 'smooth'});
      });

      document.getElementById('saveToCalendarBtn').addEventListener('click', saveToCalendar);

      activateNav();
      initScrollReveal();
    });

    // Make saveToCalendar global
    window.saveToCalendar = saveToCalendar;
  </script>
</body>
</html>"}

